toks = X.astype(int)
pred = run(X).argmax(1)
from itertools import combinations
for r in [1,2,3]:
    for sub in combinations(range(5), r):
        key = sum(toks[:,s]*(5**i) for i,s in enumerate(sub))
        # consistent?
        d = {}
        ok = True
        for k,p in zip(key,pred):
            if k in d and d[k]!=p: ok=False;break
            d[k]=p
        if ok: print("depends on", sub, len(d))

